1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.CheckDigit;
8	import org.springframework.samples.petclinic.mapper.FiscalYear;
9	import org.springframework.samples.petclinic.mapper.Locality;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's unified {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'}:
15	 * REGION is the region code derived from the owner's postcode (via {@link Locality}, postcode first
16	 * then city); FY is the two-digit fiscal year of the owner's registration date (via
17	 * {@link FiscalYear}); HASH8 is the first 8 upper-case hex characters of SHA-256 over the normalised
18	 * telephone concatenated with the last name (the same value used by the region-and-hash identity);
19	 * and CHK is a single {@link CheckDigit Luhn check digit} computed over the digits of
20	 * {@code '<REGION><FY><HASH8>'}.
21	 *
22	 * <p>When the computed member id collides with an existing owner's {@code memberId}, {@code '-<n>'}
23	 * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
24	 * always end up with distinct member ids. Mutates the built owner in place before it is saved.
25	 */
26	public class AssignMemberId {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = Locality.of(owner.getCity(), owner.getPostcode());
30	        String fy = String.format("%02d", FiscalYear.yearSegment(owner.getRegistrationDate()));
31	        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
32	        String core = region + fy + hash8;
33	        String base = core + CheckDigit.of(core);
34	
35	        Set<String> taken = new HashSet<>();
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (existing.getMemberId() != null) {
38	                taken.add(existing.getMemberId());
39	            }
40	        }
41	
42	        String memberId = base;
43	        for (int n = 2; taken.contains(memberId); n++) {
44	            memberId = base + "-" + n;
45	        }
46	        owner.setMemberId(memberId);
47	    }
48	}
