3	/**
4	 * Immutable structured audit event emitted when an owner is created.
5	 *
6	 * <p>Serialised to a compact JSON object
7	 * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} and written to the
8	 * {@code AUDIT} logger. {@code seq} is a monotonically increasing integer across creates and
9	 * {@code memberId} holds the owner's current primary identifier (see
10	 * {@link org.springframework.samples.petclinic.mapper.PrimaryIdentifier}).
11	 *
12	 * <p>The record is deeply immutable (all components are values), so once emitted the event cannot be
13	 * altered.
14	 */
15	public record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, int membershipLevel,
16	        String event) {
17	
18	    /** The marker every create event carries. */
19	    public static final String OWNER_CREATED = "OWNER_CREATED";
20	
21	    /** Compact JSON rendering with fields in the documented order. */
22	    public String toJson() {
23	        return "{\"seq\":" + this.seq
24	                + ",\"ownerId\":" + this.ownerId
25	                + ",\"memberId\":" + jsonString(this.memberId)
26	                + ",\"membershipLevel\":" + this.membershipLevel
27	                + ",\"event\":" + jsonString(this.event)
28	                + "}";
29	    }
30	
31	    /** A JSON string literal for {@code value}, or {@code null} when absent. */
32	    private static String jsonString(String value) {
33	        if (value == null) {
34	            return "null";
35	        }
36	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
37	        for (int i = 0; i < value.length(); i++) {
38	            char c = value.charAt(i);
39	            switch (c) {
40	                case '"' -> sb.append("\\\"");
41	                case '\\' -> sb.append("\\\\");
42	                case '\n' -> sb.append("\\n");
43	                case '\r' -> sb.append("\\r");
44	                case '\t' -> sb.append("\\t");
45	                default -> {
46	                    if (c < 0x20) {
47	                        sb.append(String.format("\\u%04x", (int) c));
48	                    }
49	                    else {
50	                        sb.append(c);
51	                    }
52	                }
53	            }
54	        }
55	        return sb.append('"').toString();
56	    }
57	}
