1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Computes the single Luhn check digit (0-9) over the digits contained in a string &mdash; the
5	 * {@code CHK} segment of an owner's {@code memberId}, taken over {@code '<REGION><FY><HASH8>'}.
6	 *
7	 * <p>Non-digit characters (the region letters and the {@code A-F} hex letters of the hash) are
8	 * ignored. The digits are processed right-to-left, doubling every second digit starting with the
9	 * rightmost; a doubled value above nine has nine subtracted. The check digit is the amount that
10	 * brings the running sum up to the next multiple of ten.
11	 */
12	public final class CheckDigit {
13	
14	    private CheckDigit() {
15	    }
16	
17	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
18	    public static int of(String s) {
19	        int sum = 0;
20	        boolean dbl = true;
21	        for (int i = s.length() - 1; i >= 0; i--) {
22	            char c = s.charAt(i);
23	            if (c < '0' || c > '9') {
24	                continue;
25	            }
26	            int d = c - '0';
27	            if (dbl) {
28	                d *= 2;
29	                if (d > 9) {
30	                    d -= 9;
31	                }
32	            }
33	            sum += d;
34	            dbl = !dbl;
35	        }
36	        return (10 - (sum % 10)) % 10;
37	    }
38	}
