2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives fiscal-year values from a date. The fiscal year runs 1 July to 30 June and is identified
8	 * by the calendar year in which it ends, so 1 July 2025 to 30 June 2026 is fiscal year 2026 and its
9	 * label is {@code FY26}.
10	 *
11	 * <p>Fed the owner's persisted (business-day-adjusted) registration date, this is the single source
12	 * of truth for the member id's FY segment and the tenure count in {@link MembershipLevel}. The
13	 * {@code fiscalYear} response field is in turn read back off that member id (see
14	 * {@link #labelOfMemberId(String)}), so they always agree.
15	 *
16	 * <p>Kept as a standalone class (not a method on {@link OwnerMapper}) so MapStruct does not mistake
17	 * it for an implicit mapping method.
18	 */
19	public final class FiscalYear {
20	
21	    private FiscalYear() {
22	    }
23	
24	    /**
25	     * The fiscal-year ordinal for {@code date}: the calendar year in which its fiscal year (1 July
26	     * to 30 June) ends. Dates in July or later belong to the fiscal year ending the next calendar
27	     * year; earlier dates belong to the one ending in the same calendar year.
28	     */
29	    public static int ordinal(LocalDate date) {
30	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
31	    }
32	
33	    /** The two-digit year segment of {@code date}'s fiscal year (its ordinal modulo 100). */
34	    public static int yearSegment(LocalDate date) {
35	        return ordinal(date) % 100;
36	    }
37	
38	    /** The fiscal-year label {@code FY<YY>} for {@code date}, e.g. {@code FY26}. */
39	    public static String label(LocalDate date) {
40	        return String.format("FY%02d", yearSegment(date));
41	    }
42	
43	    /**
44	     * The fiscal-year label {@code FY<YY>} carried by a {@code '<REGION><FY><HASH8><CHK>'} member id
45	     * &mdash; its two-digit year segment, which directly follows the leading region letters. So the
46	     * response's {@code fiscalYear} references the unified member id rather than recomputing from the
47	     * registration date, and the two cannot disagree. Returns {@code null} when the member id is
48	     * absent or carries no two-digit year segment.
49	     */
50	    public static String labelOfMemberId(String memberId) {
51	        if (memberId == null) {
52	            return null;
53	        }
54	        int i = 0;
55	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
56	            i++;
57	        }
58	        if (i + 2 > memberId.length()
59	                || !Character.isDigit(memberId.charAt(i)) || !Character.isDigit(memberId.charAt(i + 1))) {
60	            return null;
61	        }
62	        return "FY" + memberId.substring(i, i + 2);
63	    }
64	
65	    /**
66	     * The number of whole fiscal years elapsed from {@code from} to {@code to}, i.e. the difference
67	     * of their fiscal-year ordinals. Zero when both fall in the same fiscal year.
68	     */
69	    public static int elapsed(LocalDate from, LocalDate to) {
70	        return ordinal(to) - ordinal(from);
71	    }
72	}
