1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Duplicate-detection step of {@code POST /api/owners}: rejects the request 409 when the new owner
11	 * duplicates an existing one. Duplicate detection is now expressed through the single
12	 * {@code identityKey} &mdash; the lower-case hex SHA-256 of
13	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + soundex(lastName)} (see
14	 * {@link OwnerIdentity#key(String, String, String)}). The separate household-duplicate 409 that was
15	 * derived from the computed {@code householdId} no longer applies.
16	 *
17	 * <p>Only an <b>exact identity</b> conflict is rejected: the whole {@code identityKey} matches an
18	 * existing owner. Because the telephone is part of the hashed input, two owners sharing a last name
19	 * and postcode but with different telephones have different keys and are both admitted &mdash; the
20	 * second is recorded downstream as a soft match by {@link FlagPossibleDuplicate} rather than
21	 * rejected here.
22	 *
23	 * <p>Runs after the normalize and email-domain steps (so telephone is E.164, email lower-cased, and
24	 * disposable domains already blocked) and before {@link BuildOwner}, so no owner is persisted on
25	 * conflict. Soft-deleted owners are ignored.
26	 */
27	public class RequireUniqueIdentity {
28	
29	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
32	                request.getLastName());
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (Boolean.TRUE.equals(existing.getDeleted())) {
35	                continue; // a soft-deleted owner no longer blocks a new registration
36	            }
37	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
38	                    existing.getLastName());
39	            if (identityKey.equals(existingKey)) {
40	                throw new DuplicateIdentityException(identityKey);
41	            }
42	        }
43	    }
44	}
