12	 * postcode &mdash; a different identity key, but a phonetically identical surname at the same
13	 * postcode &mdash; it is still created but recorded as a possible duplicate: its
14	 * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the matching owner's id
15	 * (the earliest-created match when there is more than one). Otherwise {@code possibleDuplicate} is
16	 * set false and {@code possibleDuplicateOf} left null.
17	 *
18	 * <p>Because the telephone is part of the identity key, two owners sharing a last name and postcode
19	 * but with different telephones now have different keys: they are no longer a hard household
20	 * duplicate but are surfaced here as a soft match.
21	 *
22	 * <p>A <em>declared</em> household member &mdash; one that opted in with {@code sharesHousehold} to
23	 * join an existing household (same last name and postcode) &mdash; is never a suspected duplicate:
24	 * its shared last name and postcode are exactly what it declared, so it is left unflagged.
25	 *
26	 * <p>Runs after {@link BuildOwner} (so it can mutate the built owner in place) and before
27	 * {@link SaveOwner}, under the write transaction. A new owner with no postcode never soft-matches.
28	 */
29	public class FlagPossibleDuplicate {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        owner.setPossibleDuplicate(false);
33	        owner.setPossibleDuplicateOf(null);
34	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
35	            return; // a declared household member is not a suspected duplicate
36	        }
37	        String postcode = owner.getPostcode();
38	        if (postcode == null || postcode.isBlank()) {
39	            return;
40	        }
41	        String soundex = OwnerIdentity.soundex(owner.getLastName());
42	        String identityKey = OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
43	        Owner match = null;
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (Boolean.TRUE.equals(existing.getDeleted())) {
46	                continue; // a soft-deleted owner is not a duplicate to flag against
47	            }
48	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
49	                continue; // never match the new owner against itself
50	            }
51	            if (!postcode.equals(existing.getPostcode())
52	                    || !soundex.equals(OwnerIdentity.soundex(existing.getLastName()))) {
53	                continue;
54	            }
55	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
56	                    existing.getLastName());
57	            if (identityKey.equals(existingKey)) {
58	                continue; // an identical identity key is a hard duplicate, not a soft match
59	            }
60	            if (match == null || existing.getId() < match.getId()) {
61	                match = existing;
62	            }
63	        }
64	        if (match != null) {
65	            owner.setPossibleDuplicate(true);
66	            owner.setPossibleDuplicateOf(match.getId());
67	        }
68	    }
69	}
