24	                + ",\"ownerId\":" + this.ownerId
25	                + ",\"memberId\":" + jsonString(this.memberId)
26	                + ",\"membershipLevel\":" + this.membershipLevel
27	                + ",\"event\":" + jsonString(this.event)
28	                + "}";
29	    }
30	
31	    /** A JSON string literal for {@code value}, or {@code null} when absent. */
32	    private static String jsonString(String value) {
33	        if (value == null) {
34	            return "null";
35	        }
36	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
37	        for (int i = 0; i < value.length(); i++) {
38	            char c = value.charAt(i);
39	            switch (c) {
40	                case '"' -> sb.append("\\\"");
41	                case '\\' -> sb.append("\\\\");
42	                case '\n' -> sb.append("\\n");
43	                case '\r' -> sb.append("\\r");
44	                case '\t' -> sb.append("\\t");
45	                default -> {
